SELECT COUNT(DISTINCT orders.order_id) AS siparis_sayisi
FROM orders
WHERE orders.order_purchase_timestamp <= (SELECT MAX(order_purchase_timestamp) FROM orders);

SELECT COUNT(DISTINCT product_category_name_english)
FROM products
JOIN product_category_name_translation ON products.product_category_name = product_category_name_translation.product_category_name;
